/// Convert a PascalCase string to snake_case.
///
/// # Examples
///
/// ```
/// use mlmd_core::plugin::scaffold::to_snake_case;
/// assert_eq!(to_snake_case("MyCustomLayer"), "my_custom_layer");
/// assert_eq!(to_snake_case("AttentionHead"), "attention_head");
/// assert_eq!(to_snake_case("ValidBlock"), "valid_block");
/// ```
pub fn to_snake_case(s: &str) -> String {
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() {
            if i > 0 {
                result.push('_');
            }
            result.push(c.to_lowercase().next().unwrap());
        } else {
            result.push(c);
        }
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_simple_block() {
        let code = generate_plugin_file("MyCustomLayer");
        assert!(code.contains("MyCustomLayer"));
        assert!(code.contains("infer_shape"));
        assert!(code.contains("pytorch_codegen"));
        assert!(code.contains("keras_codegen"));
        assert!(code.contains("candle_codegen"));
    }

    #[test]
    fn test_generate_snake_case_name() {
        let code = generate_plugin_file("AttentionHead");
        assert!(code.contains("AttentionHead"));
        assert!(code.contains("attention_head"));
    }

    #[test]
    fn test_generate_valid_rust() {
        // Verify the generated code is valid Rust by checking syntax basics
        let code = generate_plugin_file("ValidBlock");
        assert!(code.contains("pub fn register()"));
        assert!(code.contains("fn pytorch_codegen"));
    }

    #[test]
    fn test_to_snake_case_basic() {
        assert_eq!(to_snake_case("MyCustomLayer"), "my_custom_layer");
    }

    #[test]
    fn test_to_snake_case_single_word() {
        assert_eq!(to_snake_case("Linear"), "linear");
    }

    #[test]
    fn test_to_snake_case_acronym() {
        assert_eq!(to_snake_case("LSTM"), "l_s_t_m");
    }
}
